-- Migration 0019 — Phase 10: channel decisions are observable and auditable
-- (gap register A6/A9: "never silently SMS -> Email").
--
-- Generated by `drizzle-kit generate` from src/schema/events.ts; this header
-- was added by hand, and the _journal.json "when" was set by hand to
-- 1792500000000 so it sorts AFTER 0018's hand-set timestamp (drizzle-kit
-- stamped it 1792122763267 — earlier than 0018 — which would silently skip
-- this migration on an already-migrated database: the recurring trap noted
-- in the Phase 8 sign-off).
--
-- events gains three nullable columns carrying a messaging event's channel
-- decision as stable, queryable fields (previously only free text inside
-- decision_reason):
--   requested_channel — the channel the message was requested on;
--   selected_channel  — the channel it was actually sent on;
--   fallback_reason   — why they differ (NULL when they don't).
-- chk_events_channel_fallback_reason makes a SILENT channel change
-- unrepresentable in the audit trail: whenever both channels are recorded,
-- fallback_reason must be NULL if they are equal and a non-blank reason if
-- they differ. Rows that predate this migration (all NULL) and
-- non-messaging events are unaffected.
--
-- Purely additive: no existing row is modified.

ALTER TABLE "events" ADD COLUMN "requested_channel" text;--> statement-breakpoint
ALTER TABLE "events" ADD COLUMN "selected_channel" text;--> statement-breakpoint
ALTER TABLE "events" ADD COLUMN "fallback_reason" text;--> statement-breakpoint
CREATE INDEX "idx_events_channel_fallback" ON "events" USING btree ("created_at") WHERE "events"."fallback_reason" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "events" ADD CONSTRAINT "chk_events_channel_fallback_reason" CHECK ("events"."requested_channel" IS NULL OR "events"."selected_channel" IS NULL OR ("events"."requested_channel" = "events"."selected_channel" AND "events"."fallback_reason" IS NULL) OR ("events"."requested_channel" <> "events"."selected_channel" AND "events"."fallback_reason" IS NOT NULL AND length(btrim("events"."fallback_reason")) > 0));
